{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_rate_counts_none_as_unflagged():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"small": [event("a", 1, True)],
              "large": [event(str(i), 1, False) for i in range(3)],
              "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (3, 9), (8, 9)])
def test_flags_in_window(days, expected):
    assert flags_in_window([2, 3, 4], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_fields_whitespace_and_skipped_lines():
    lines = ["\n", "  # comment, not, a record", "   ",
             " a ,  -2 , 1 ", "b, 0, 0", " c, 3,   "]
    assert parse_transcript_log(lines) == [
        event("a", -2, True), event("b", 0, False), event("c", 3, None)
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,no,1"])
def test_parse_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["\n", " # comment", "ok,1,1", bad_line])


def test_dedupe_keeps_last_duplicate_and_sorts_by_day_then_id():
    original = event("x", 5, True)
    replacement = event("x", 1, None)
    events = [original, event("z", 1, True), event("a", 1, False),
              event("b", 0, True), replacement]
    assert dedupe_transcripts(events) == [events[3], events[2], replacement, events[1]]
    assert dedupe_transcripts([]) == []


def test_daily_counts_include_empty_days_and_ignore_outside_range():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, False), event("e", 2, None), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 2) == []


def test_summary_uses_calendar_days_pooled_rate_and_nonempty_group_count():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 2, False), event("c", 4, False)],
              "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_sorts_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "b": [event("b", 1, True)], "a": [event("a", 1, False)]}
    assert top_flagged_groups(groups, 5) == ["b", "z", "a"]
    assert top_flagged_groups(groups, 1) == ["b"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_resets_on_nonpositive_values():
    assert longest_flag_streak([1, 2, 0, 1, -1, 3, 4, 5]) == 3
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
